def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 56.0))
        return float(min(budget, 18.0))

    prev_bids = []
    aggressive_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= 90:
                aggressive_bids.append(float(bid))
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 500:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    medium_supply = supply <= 20

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 1:
        urgency += 2

    if tight_supply:
        urgency += 2
    elif medium_supply:
        urgency += 1

    if desperate_count >= 1:
        urgency += 1
    if rich_count >= 2 and highest_prev >= 90:
        urgency += 1

    if urgency >= 6:
        target = max(98.0, highest_prev + 1.5)
    elif urgency >= 4:
        target = max(78.0, min(96.0, highest_prev + 1.0))
    elif urgency >= 2:
        if highest_prev >= 95:
            target = 52.0
        else:
            target = max(46.0, avg_prev * 0.7)
    else:
        if highest_prev >= 90:
            target = 22.0
        else:
            target = 35.0

    if day >= 8:
        target += 6.0
    if hp <= 2:
        target += 4.0
    if no_water_days >= 1:
        target += 6.0

    max_safe = budget
    if day < 9:
        reserve_days = 10 - day
        reserve_amount = reserve_days * 8.0
        max_safe = max(0.0, budget - reserve_amount)
        if urgency >= 4:
            max_safe = budget

    bid = min(target, budget)
    if max_safe > 0:
        bid = min(bid, max_safe) if urgency < 4 else min(target, budget)

    if hp <= 2 or no_water_days >= 1:
        bid = max(bid, min(budget, 60.0))

    if bid < 0:
        bid = 0.0
    return float(round(min(bid, budget), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive.append((oid, o))

    # If no opponents, just bid conservatively
    if not alive:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.4))

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Read yesterday bids from traces (only immediate reaction)
    yesterday_bids = []
    for _, o in alive:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = 0.0
    if len(yesterday_bids) >= 2:
        sorted_b = sorted(yesterday_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Supply pressure: lower supply => more competitive
    # Map supply to a multiplier without indexing lists.
    if supply <= MIN_SUPPLY:
        supply_mult = 1.15
    elif supply >= MAX_SUPPLY:
        supply_mult = 0.95
    else:
        # Linear interpolation between 1.15 and 0.95
        supply_mult = 1.15 - (supply - MIN_SUPPLY) * (1.15 - 0.95) / (MAX_SUPPLY - MIN_SUPPLY)

    # If we are in danger of running out of water, bid harder.
    danger = 0
    if no_water_days >= 2:
        danger = 1
    if hp <= 2:
        danger = 2

    # Cindy/Eric were high bidders and survived; we should not be too low.
    # Target: slightly above the previous high bidder when in danger, otherwise just above a mid level.
    if danger == 2:
        target = max(highest_prev_bid * 1.02, second_prev_bid * 1.05, DAILY_SALARY * 0.85)
    elif danger == 1:
        target = max(second_prev_bid * 1.03, highest_prev_bid * 0.98, DAILY_SALARY * 0.70)
    else:
        # Not in immediate danger: bid enough to beat aggressive bidders but conserve.
        # Use a fraction of highest_prev_bid if they were extremely high.
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            target = max(DAILY_SALARY * 0.62, highest_prev_bid * 0.80)
        else:
            target = max(DAILY_SALARY * 0.55, highest_prev_bid + 1.5)

    # Convert target to a budget-limited bid.
    # Also cap to avoid bankrupting ourselves unnecessarily.
    cap = max(0.0, budget)
    # Soft cap: never bid more than 1.0 salary unless in extreme danger.
    if danger == 0:
        cap = min(cap, DAILY_SALARY * 0.75)
    elif danger == 1:
        cap = min(cap, DAILY_SALARY * 0.95)
    else:
        cap = min(cap, DAILY_SALARY * 1.10)

    bid = min(cap, target * supply_mult)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)
